{
  "candidate_edge_types": [
    {
      "name": "INFORMS_SUBSEQUENT_PLAN",
      "definition": "An observation of specifications or reference material is used to derive the semantics that shape the agent's subsequent design or plan.",
      "source_description": "An observation revealing the specification or behavior of a relevant system.",
      "target_description": "A subsequent plan or design decision grounded in that observation."
    },
    {
      "name": "VERIFIES_GENERATED_ARTIFACT",
      "definition": "A subsequent execution step exercises or inspects an artifact produced by an earlier action to confirm it behaves as required.",
      "source_description": "A generated artifact or produced output from an earlier action.",
      "target_description": "A subsequent step that runs or inspects that artifact to check its correctness."
    },
    {
      "name": "EXTENDS_VERIFICATION_COVERAGE",
      "definition": "After an initial verification succeeds, a subsequent step performs additional or broader tests on the same subject.",
      "source_description": "A successful initial verification result.",
      "target_description": "A subsequent verification action that expands test coverage."
    },
    {
      "name": "CONSUMES_PRIOR_OUTPUT_AS_INPUT",
      "definition": "A value or artifact produced by an earlier action is fed as an input into a subsequent action.",
      "source_description": "An output, value, or artifact produced by an earlier action.",
      "target_description": "A subsequent action that consumes that output as an input."
    },
    {
      "name": "TRIGGERS_TASK_COMPLETION",
      "definition": "A verification result confirming that the produced solution satisfies the requirements leads the agent to decide the task is complete.",
      "source_description": "A verification observation confirming the correctness of the solution.",
      "target_description": "A decision or action to finalize and mark the task complete."
    }
  ]
}

